'use client';

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ShoppingBag, Tag, Clock } from 'lucide-react';
import { motion, useMotionValue, useTransform, animate } from 'framer-motion';
import { IoIosArrowBack } from 'react-icons/io';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* -------------------- CONSTANTS -------------------- */

const TABS = ['all', 'orders', 'promotions'] as const;
type TabType = typeof TABS[number];

const TAB_TYPE_MAP: Record<TabType, string[]> = {
  all: ['order', 'promo'],
  orders: ['order'],
  promotions: ['promo'],
};

const MOCK_NOTIFICATIONS = [
  {
    id: '1',
    type: 'order',
    title: 'Order Shipped',
    message: 'Your order #FF-2025 has been shipped. Track your shipment now.',
    timestamp: '2 mins ago',
  },
  {
    id: '2',
    type: 'promo',
    title: 'Flash Sale Alert',
    message: 'The Monochrome Collection is now 40% off. Limited time only.',
    timestamp: '1 hour ago',
  },
  {
    id: '3',
    type: 'order',
    title: 'Order Delivered',
    message: 'Order #FF-2023 has been delivered at your doorstep.',
    timestamp: '2 days ago',
  },
  {
    id: '4',
    type: 'promo',
    title: 'Exclusive Access',
    message: 'Early access unlocked for our anniversary sale.',
    timestamp: '3 days ago',
  },
  {
    id: '5',
    type: 'order',
    title: 'Refund Initiated',
    message: 'Your refund for order #FF-1954 has been initiated.',
    timestamp: '1 week ago',
  },
  {
    id: '6',
    type: 'promo',
    title: 'Free Shipping',
    message: 'Free shipping on all prepaid orders this weekend.',
    timestamp: '2 weeks ago',
  },
];

/* -------------------- COMPONENTS -------------------- */

function NotificationItem({ n }: { n: any }) {
  return (
    <div className="flex gap-4 p-5 border-b border-border hover:bg-background-muted/50 transition-colors">
      <div className="w-11 h-11 shrink-0 rounded-full bg-brand flex items-center justify-center">
        {n.type === 'order' ? (
          <ShoppingBag className="w-5 h-5 text-brand-foreground" />
        ) : (
          <Tag className="w-5 h-5 text-brand-foreground" />
        )}
      </div>

      <div className="flex-1 space-y-1">
        <div className="flex justify-between items-start gap-3">
          <h3 className="text-sm font-semibold text-foreground">
            {n.title}
          </h3>
          <span className="text-xs text-foreground-subtle flex items-center gap-1 whitespace-nowrap">
            <Clock className="w-3 h-3" />
            {n.timestamp}
          </span>
        </div>
        <p className="text-sm text-foreground-muted leading-relaxed">
          {n.message}
        </p>
      </div>
    </div>
  );
}

/* -------------------- PAGE -------------------- */

export default function NotificationsPage() {
  const [activeIndex, setActiveIndex] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  const x = useMotionValue(0);

  useEffect(() => {
    if (containerRef.current) {
      setContainerWidth(containerRef.current.offsetWidth);
    }
  }, []);

  /* Sync active tab while dragging */
  useEffect(() => {
    const unsub = x.on('change', (latest) => {
      const index = Math.round(Math.abs(latest / containerWidth));
      if (index !== activeIndex && index >= 0 && index < TABS.length) {
        setActiveIndex(index);
      }
    });
    return () => unsub();
  }, [activeIndex, containerWidth, x]);

  const indicatorX = useTransform(
    x,
    [0, -containerWidth, -containerWidth * 2],
    ['0%', '100%', '200%']
  );

  const handleTabClick = (index: number) => {
    setActiveIndex(index);
    animate(x, -index * containerWidth, {
      type: 'spring',
      bounce: 0.15,
      duration: 0.5,
    });
  };

  const handleDragEnd = (_: any, info: any) => {
    const threshold = 60;

    if (info.offset.x < -threshold && activeIndex < TABS.length - 1) {
      handleTabClick(activeIndex + 1);
      return;
    }

    if (info.offset.x > threshold && activeIndex > 0) {
      handleTabClick(activeIndex - 1);
      return;
    }

    handleTabClick(activeIndex);
  };

  const getNotificationsByTab = (tab: TabType) =>
    MOCK_NOTIFICATIONS.filter((n) =>
      TAB_TYPE_MAP[tab].includes(n.type)
    );

  return (
    <div className="min-h-screen flex flex-col bg-background text-foreground">
      {/* HEADER */}
      <header className="sticky top-0 z-10 bg-background/80 backdrop-blur border-b border-border">
        <div className="max-w-2xl mx-auto h-16 px-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <IoIosArrowBack className="text-2xl cursor-pointer" />
            <h1 className="text-xl font-bold">Notifications</h1>
          </div>
          <button className="text-xs font-medium text-foreground-subtle hover:text-foreground">
            Mark all read
          </button>
        </div>

        {/* TABS */}
        <div className="max-w-2xl mx-auto px-4 relative">
          <nav className="flex">
            {TABS.map((tab, i) => (
              <button
                key={tab}
                onClick={() => handleTabClick(i)}
                className={cn(
                  'flex-1 pb-3 text-sm font-medium capitalize transition-colors',
                  activeIndex === i
                    ? 'text-foreground'
                    : 'text-foreground-subtle'
                )}
              >
                {tab}
              </button>
            ))}
          </nav>

          <motion.div
            style={{ x: indicatorX, width: `${100 / TABS.length}%` }}
            className="absolute bottom-0 left-0"
          >
            <div className="h-0.5 bg-brand w-full" />
          </motion.div>
        </div>
      </header>

      {/* SLIDER */}
      <main
        ref={containerRef}
        className="relative flex-1 max-w-2xl mx-auto w-full h-full overflow-hidden"
      >
        <motion.div
          drag="x"
          dragConstraints={{
            left: -containerWidth * (TABS.length - 1),
            right: 0,
          }}
          style={{ x }}
          onDragEnd={handleDragEnd}
          className="flex h-full w-[300%] touch-pan-y cursor-grab active:cursor-grabbing"
        >
          {TABS.map((tab) => {
            const items = getNotificationsByTab(tab);
            return (
              <section
                key={tab}
                className="w-full h-full shrink-0 overflow-y-auto"
              >
                {items.length === 0 ? (
                  <div className="py-20 text-center text-foreground-subtle">
                    No {tab} notifications
                  </div>
                ) : (
                  items.map((n) => (
                    <NotificationItem key={n.id} n={n} />
                  ))
                )}
              </section>
            );
          })}
        </motion.div>
      </main>
    </div>
  );
}
